+}
+
+export function serverResourceReasons(stages, identity) {
+  const reasons = [];
+  invariant(/^\d+$/.test(identity?.affinity) && typeof identity.cgroupCpuMax === 'string' && identity.cgroupCpuMax.length > 0,
